+:root {
+  --ink: #17232b;
+  --muted: #64737b;
+  --line: #dce5e6;
+  --surface: #ffffff;
+  --canvas: #f5f8f7;
+  --teal: #087f78;
+  --teal-dark: #075c59;
+  --teal-soft: #e6f4f1;
