+input:focus { border-color: var(--teal); box-shadow: 0 0 0 3px rgba(8, 127, 120, .14); }
+.hint { margin: 6px 0 0; color: var(--muted); font-size: 12px; }
+.form-actions { display: flex; gap: 10px; margin-top: 20px; }
+.button { min-height: 42px; padding: 8px 16px; border: 1px solid transparent; border-radius: 4px; font-weight: 700; transition: background .15s, border-color .15s, transform .15s; }
+.button:hover { transform: translateY(-1px); }
+.button-primary { color: #fff; background: var(--teal); }
+.button-primary:hover { background: var(--teal-dark); }
+.button-quiet { color: var(--muted); background: #fff; border-color: var(--line); }
