const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');

function schedule(start, limit, courses) {
  const ordered = courses.map((course) => ({ ...course, remaining: course.hours }))
    .sort((a, b) => a.exam.localeCompare(b.exam));
  const plan = [];
  let day = new Date(`${start}T00:00:00Z`);
  const latest = ordered.reduce((value, course) => course.exam > value ? course.exam : value, start);
  while (day.toISOString().slice(0, 10) < latest && ordered.some((course) => course.remaining > 0)) {
    const date = day.toISOString().slice(0, 10);
    let available = limit;
    for (const course of ordered) {
      if (available <= 0 || course.remaining <= 0 || date >= course.exam) continue;
      const hours = Math.min(available, course.remaining);
      plan.push({ date, course: course.name, hours });
      course.remaining -= hours;
      available -= hours;
    }
    day.setUTCDate(day.getUTCDate() + 1);
  }
  return { plan, remaining: ordered.reduce((sum, course) => sum + course.remaining, 0) };
}

test('static project contract exists', () => {
  for (const file of ['index.html', 'styles.css', 'app.js', 'README.md']) assert.equal(fs.existsSync(file), true, file);
  const html = fs.readFileSync('index.html', 'utf8');
  for (const marker of ['开始日期', '每日上限（小时）', '课程名称', '考试日期', '剩余小时', '添加课程', '生成计划', '课程列表', '复习计划', 'role="status"']) assert.match(html, new RegExp(marker));
});

test('schedule respects daily limit and excludes exam day', () => {
  const result = schedule('2025-06-01', 1.5, [{ name: '数学', exam: '2025-06-04', hours: 3 }]);
  assert.deepEqual(result.plan, [
    { date: '2025-06-01', course: '数学', hours: 1.5 },
    { date: '2025-06-02', course: '数学', hours: 1.5 }
  ]);
  assert.equal(result.remaining, 0);
  assert.equal(schedule('2025-06-04', 2, [{ name: '物理', exam: '2025-06-04', hours: 2 }]).plan.length, 0);
});

test('short capacity reports remaining hours', () => {
  const result = schedule('2025-06-01', 1, [{ name: '化学', exam: '2025-06-03', hours: 5 }]);
  assert.equal(result.remaining, 3);
  assert.ok(result.plan.every((item) => item.hours <= 1 && item.date < '2025-06-03'));
});

