const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');

function makePlan(start, limit, course) {
  const plan = [];
  let remaining = course.hours;
  let day = new Date(`${start}T00:00:00Z`);
  while (day.toISOString().slice(0, 10) < course.exam && remaining > 0) {
    const date = day.toISOString().slice(0, 10);
    const hours = Math.min(limit, remaining);
    plan.push({ date, hours });
    remaining -= hours;
    day.setUTCDate(day.getUTCDate() + 1);
  }
  return { plan, remaining };
}

test('project files and required UI contract exist', () => {
  for (const file of ['index.html', 'styles.css', 'app.js', 'README.md']) assert.equal(fs.existsSync(file), true, file);
  const html = fs.readFileSync('index.html', 'utf8');
  for (const marker of ['开始日期', '每日上限（小时）', '课程名称', '考试日期', '剩余小时', '添加课程', '生成计划', '课程列表', '复习计划', 'role="status"']) assert.ok(html.includes(marker), marker);
});

test('schedule stays within capacity and before exam day', () => {
  const result = makePlan('2025-06-01', 1.5, { exam: '2025-06-04', hours: 3 });
  assert.deepEqual(result.plan, [{ date: '2025-06-01', hours: 1.5 }, { date: '2025-06-02', hours: 1.5 }]);
  assert.equal(result.remaining, 0);
  assert.deepEqual(makePlan('2025-06-04', 2, { exam: '2025-06-04', hours: 2 }).plan, []);
});

